  transition: color 160ms ease, border-color 160ms ease;
}
.tabs-nav__btn:hover { color: var(--ink); }
.tabs-nav__btn.is-active { color: var(--ink); border-bottom-color: var(--accent); }
.tabs-nav__btn .count {
