  padding: 12px 14px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.meta-tile__label { font-size: 11px; color: var(--muted); font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; }
.meta-tile__value { font-family: var(--font-display); font-weight: 700; font-size: 16px; margin-top: 2px; }
.service-detail__seller {
  display: flex; align-items: center; gap: 10px;
  padding: 12px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 10px;
  margin: 16px 0;
}

/* Toasts */
.toast-stack {
  position: fixed; bottom: 24px; right: 24px;
  display: flex; flex-direction: column; gap: 10px;
  z-index: 80;
}
.toast {
  min-width: 280px; max-width: 380px;
  padding: 12px 14px;
  border-radius: 12px;
  background: var(--surface);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-md);
  display: flex; gap: 10px; align-items: flex-start;
  animation: toastIn 220ms ease both;
}
@keyframes toastIn {
  from { transform: translateX(20px); opacity: 0; }
  to   { transform: translateX(0); opacity: 1; }
}
.toast.is-leaving {
  animation: toastOut 200ms ease both;
}
@keyframes toastOut {
  from { transform: translateX(0); opacity: 1; }
  to   { transform: translateX(20px); opacity: 0; }
}
.toast__icon {
  width: 28px; height: 28px; border-radius: 8px;
  display: grid; place-items: center;
  flex: 0 0 auto;
}
.toast--success .toast__icon { background: var(--green-soft); color: var(--green); }
.toast--error .toast__icon { background: var(--red-soft); color: var(--red); }
.toast--info .toast__icon { background: var(--blue-soft); color: var(--blue); }
.toast__msg { font-size: 14px; color: var(--ink-2); line-height: 1.4; }

/* Footer */
.footer {
  position: relative; z-index: 1;
  border-top: 1px solid var(--line);
  background: var(--surface);
  padding: 20px 24px;
}
.footer__inner {
  max-width: 1240px; margin: 0 auto;
  display: flex; justify-content: space-between; align-items: center;
  gap: 16px; flex-wrap: wrap;
  font-size: 13px; color: var(--muted);
}
.footer__brand { font-weight: 700; color: var(--ink-2); }
.footer__meta { display: flex; gap: 10px; align-items: center; }
.footer__dot { opacity: 0.5; }

/* Utilities */
.hidden { display: none !important; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.mono { font-family: var(--font-mono); }
.divider { height: 1px; background: var(--line); margin: 16px 0; }

/* Responsive */
@media (max-width: 1024px) {
  .dash-stats { grid-template-columns: repeat(2, 1fr); }
  .dash-grid { grid-template-columns: 1fr; }
}

@media (max-width: 860px) {
  .hero {
    grid-template-columns: 1fr;
    padding: 36px 24px;
  }
  .hero__right { grid-template-columns: repeat(2, 1fr); }
  .hero__scroll { grid-template-columns: 1fr; }
  .auth-card { grid-template-columns: 1fr; }
  .auth-side { display: none; }
  .form-row { grid-template-columns: 1fr; }
}

@media (max-width: 780px) {
  .main-nav {
    position: absolute; top: 100%; left: 0; right: 0;
    flex-direction: column;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 10px 16px 16px;
    gap: 2px;
    box-shadow: var(--shadow-md);
    transform: translateY(-8px); opacity: 0;
    pointer-events: none;
    transition: all 180ms ease;
  }
  .main-nav.is-open {
    transform: translateY(0); opacity: 1; pointer-events: auto;
  }
  .nav-link { width: 100%; }
  .nav-link.is-active::after { display: none; }
  .nav-link.is-active { background: var(--surface-2); }
  .nav-toggle { display: block; }
  .brand__sub { display: none; }
  .userbox__name { display: none; }
  .page-header { flex-direction: column; align-items: stretch; }
  .page-header__title { font-size: 28px; }
  .toast-stack { left: 16px; right: 16px; bottom: 16px; }
  .toast { min-width: 0; }
}

@media (max-width: 520px) {
  .hero__right { grid-template-columns: 1fr; }
  .app { padding: 20px 14px 80px; }
  .service-detail__meta { grid-template-columns: 1fr; }
  .tabs { width: 100%; }
  .tabs__btn { flex: 1; }
  .dash-stats { grid-template-columns: 1fr 1fr; }
}

