      <table class="data">
        <thead><tr><th>Serviço</th><th>Prestador</th><th>Contratante</th><th>Status</th></tr></thead>
        <tbody>${rows || `<tr><td colspan="4"><div class="empty" style="border:0;background:transparent">Nenhum contrato ainda.</div></td></tr>`}</tbody>
      </table>
